                                $pushLastAnyChangeAt = $nowSeen
                            } elseif (-not $pushLayerLastChanged.ContainsKey($layer)) {
                                $pushLayerLastChanged[$layer] = $nowSeen
                            }
                            $pushLayerStatus[$layer] = $status
